  PARTITION p20261015 VALUES LESS THAN ('2026-10-16 00:00:00'),
  PARTITION p20261016 VALUES LESS THAN ('2026-10-17 00:00:00'),
  PARTITION p20261017 VALUES LESS THAN ('2026-10-18 00:00:00'),
  PARTITION p20261018 VALUES LESS THAN ('2026-10-19 00:00:00'),
  PARTITION p20261019 VALUES LESS THAN ('2026-10-20 00:00:00'),
  PARTITION p20261020 VALUES LESS THAN ('2026-10-21 00:00:00'),
  PARTITION p20261021 VALUES LESS THAN ('2026-10-22 00:00:00'),
  PARTITION p20261022 VALUES LESS THAN ('2026-10-23 00:00:00'),
  PARTITION p20261023 VALUES LESS THAN ('2026-10-24 00:00:00'),
  PARTITION p20261024 VALUES LESS THAN ('2026-10-25 00:00:00'),
  PARTITION p20261025 VALUES LESS THAN ('2026-10-26 00:00:00'),
  PARTITION p20261026 VALUES LESS THAN ('2026-10-27 00:00:00'),
